-- Payments
ON CONFLICT (payment_method_id) DO NOTHING;

SELECT 
    r.reservation_id AS payment_id,
    r.reservation_id,
    ((r.reservation_id % 3) + 1) AS payment_method_id,
    r.final_amount AS amount,
    r.created_at AS payment_date,
    'SUCCESSFUL' AS status
FROM reservations r
WHERE r.status_id IN (2, 3, 4)
ON CONFLICT (payment_id) DO UPDATE SET amount=EXCLUDED.amount, status=EXCLUDED.status;

-- Refund Reasons & Refunds
ON CONFLICT (refund_reason_id) DO NOTHING;

SELECT 
    (ROW_NUMBER() OVER (ORDER BY r.reservation_id)) AS refund_id,
    r.reservation_id,
    p.payment_id,
    r.created_at + INTERVAL '1 day' AS refund_date,
    r.final_amount AS refund_amount,
    ((r.reservation_id % 4) + 1) AS refund_reason_id,
    'BANK_TRANSFER' AS refund_method,
    ('REF-' || r.reservation_id) AS reference_number,
    'APPROVED' AS status
FROM reservations r
LEFT JOIN payments p ON p.reservation_id = r.reservation_id
WHERE r.status_id = 5 OR r.discount_amount > 2000
ON CONFLICT (refund_id) DO UPDATE SET refund_amount=EXCLUDED.refund_amount;

-- Expenses
ON CONFLICT (expense_category_id) DO NOTHING;

ON CONFLICT (expense_id) DO UPDATE SET amount=EXCLUDED.amount, description=EXCLUDED.description;

